import { mock } from 'bun:test';
import assert from 'node:assert/strict';
import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { MemoryRouter } from 'react-router-dom';
mock.module('../../src/hooks/ui/useUiTranslation', () => ({ useUiTranslation: () => {} }));
mock.module('../../src/hooks/ui/useMobileAppearance', () => ({ useMobileAppearance: () => false }));
mock.module('../../src/hooks/ui/useMotionPreference', () => ({ useMotionPreference: () => true }));
mock.module('../../src/hooks/ui/useVisibleAutoplay', () => ({ useVisibleAutoplay: () => ({ ref: { current: null }, visible: false }) }));
mock.module('../../src/components/playlist/AddToPlaylistButton', () => ({ AddToPlaylistButton: () => null }));
mock.module('../../src/lib/api', () => ({ getHighQualityImage: (url: string) => url, getHighQualityPoster: (url: string) => url, getProxiedImageUrl: (url: string) => url }));
mock.module('../../src/lib/animeIdMapping', () => ({ buildPreferredAnimeRouteId: (item: any) => item.id }));
mock.module('../../src/components/tv/TVVideoBackdrop', () => ({ TVTrailerPreview: () => null }));
mock.module('../../src/components/tv/TVHeroChrome', () => ({ TVHeroFacts: ({ facts }: any) => <div className="tv-hero-facts">{facts.join(' · ')}</div>, TVPreviewToggle: () => null }));
mock.module('../../src/components/layout/AppThemeBackground', () => ({ useAppSystemBlur: () => false, useAppBackdropPortal: () => null }));
const { SpotlightPresentationProvider } = await import('../../src/components/customization/SpotlightPresentation');
const { HeroSection } = await import('../../src/components/anime/HeroSection');
const { CinematicHero } = await import('../../src/components/anime/CinematicHero');
const { TVCinematicHero } = await import('../../src/components/tv/TVCinematicHero');
const source: any = { id: '42', name: 'Featured title', poster: '/poster.jpg', banner: '/banner.jpg', description: 'A story synopsis', rank: 1, otherInfo: ['TV', '2026'], episodes: { sub: 12, dub: 0 } };
const classic = <HeroSection spotlight={source} hideCatalogActions />;
const render = (content: React.ReactNode, presentation?: any) => renderToStaticMarkup(<MemoryRouter><SpotlightPresentationProvider presentation={presentation}>{content}</SpotlightPresentationProvider></MemoryRouter>);
assert.equal(render(classic), render(classic, {}));
assert(!render(classic).includes('data-custom-spotlight'));
const configuration = { height: 520, titleSize: 38, titleAlign: 'right', shade: .45, showDescription: false, showMetadata: false };
const styled = render(classic, configuration);
assert(styled.includes('--spotlight-height:520px'));
assert(styled.includes('--spotlight-title-size:38px'));
assert(styled.includes('data-spotlight-description="false"'));
assert(styled.includes('data-spotlight-metadata="false"'));
assert(styled.includes('data-spotlight-stage'));
assert(styled.includes('data-spotlight-copy'));
assert(styled.includes('src="/banner.jpg"'));
assert(styled.includes('Featured title'));
Object.assign(globalThis, { document: { hidden: false } });
const selectedCinematic = render(classic, { ...configuration, variant: 'cinematic' });
assert(selectedCinematic.includes('class="cinematic-hero"'));
assert(selectedCinematic.includes('cinematic-title spotlight-heading'));
assert(selectedCinematic.includes('max-w-[720px]'));
assert(selectedCinematic.includes('sm:flex-none'));
assert(!selectedCinematic.includes('classic-spotlight-mobile'));
const selectedClassic = render(classic, { ...configuration, variant: 'classic' });
assert(selectedClassic.includes('classic-spotlight-mobile'));
const cinematic = render(<CinematicHero spotlights={[source]} hideCatalogActions />, configuration);
assert(cinematic.includes('data-spotlight-stage'));
assert(cinematic.includes('data-spotlight-shade'));
assert(cinematic.includes('src="/poster.jpg"'));
const tv = render(<TVCinematicHero title={source.name} artwork={source.banner} facts={source.otherInfo} description={source.description} actions={<a href="/anime/42">Open title</a>} />, configuration);
assert(tv.includes('data-spotlight-stage'));
assert(tv.includes('data-spotlight-copy'));
assert(tv.includes('data-spotlight-description'));
assert(tv.includes('href="/anime/42"'));
const tvClassic = render(<TVCinematicHero title={source.name} artwork={source.banner} facts={source.otherInfo} description={source.description} actions={<a href="/anime/42">Open title</a>} />, { variant: 'classic' });
assert(tvClassic.includes('data-spotlight-variant="classic"'));
console.log('spotlight checks passed');
